// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        c.initialize();
        address initialOwner = c.owner();
        vm.prank(caller);
        bool success;
        try c.transferOwnership(newOwner) { success = true; } catch { success = false; }
        if (success) {
            assertTrue(caller == initialOwner);
        }
    }
}
